(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx = w1x + Math.sin((x+w1x)*0.04-t*0.5)*5 + Math.cos((y+w1y)*0.035+t*0.4)*4;
  const wy = w1y + Math.cos((y+w1y)*0.04+t*0.45)*5 + Math.sin((x+w1x)*0.03-t*0.55)*4;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.13,1.8]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.4+3.0)*0.5;
  }
  const act=aS/8,inh=iS/8,harm=hS/8;
  let bg=0;
  bg+=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  bg+=(Math.sin(sx*0.08+sy*0.05+t*1.6)+Math.sin(sx*0.06-sy*0.08+t*2.2))/4;
  bg+=(Math.sin(sx*0.16+sy*0.1+t*3.2)+Math.sin(sx*0.12-sy*0.16+t*4.4))/8;
  bg+=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.08+ang*5+t*0.8)+Math.sin(dist*0.06-ang*2+t*1.0))*0.2;
  const ring1=Math.sin(dist*0.15-t*2.0)*Math.cos(ang*6+t*0.3)*0.15;
  const ring2=Math.sin(dist*0.12+t*1.5)*Math.sin(ang*8-t*0.5)*0.1;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2+ring1+ring2+harm*0.4)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.3-t*0.8)*Math.sin(sy*0.25+t*0.6)*0.3)*1.5)*0.3;
  const dx=Math.sin((sx+1)*0.15)*Math.sin(sy*0.15)-Math.sin((sx-1)*0.15)*Math.sin(sy*0.15);
  const dy=Math.sin(sx*0.15)*Math.sin((sy+1)*0.15)-Math.sin(sx*0.15)*Math.sin((sy-1)*0.15);
  const edge=Math.sqrt(dx*dx+dy*dy)*2.0;
  const blend=reaction*0.6+cell*0.25+edge*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,45],[12,45,85],[18,95,120],[25,155,145],[80,195,160],[180,210,120],[220,185,75],[215,140,65],[195,95,70],[140,55,75],[70,25,55],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(harm)*0.1;
  const glow=Math.max(0,reaction)*0.3;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum+glow*30)|0)
  ];
}
